-- Import logSP 2026 contest calendar into the project SQLite database.
-- Snapshot: 2026-10-08; 290 events; 182 PDF regulations linked.
-- Rule notes contain concise source metadata and official links, not copied full regulation text.
-- No ContestRule scoring values are inferred from bands/modes metadata.
-- Re-runnable: existing contests, editions, and source notes are left unchanged.
PRAGMA foreign_keys = ON;
BEGIN IMMEDIATE;
DROP TABLE IF EXISTS temp.logsp_2026_import;
CREATE TEMP TABLE logsp_2026_import (
    source_id TEXT PRIMARY KEY,
    contest_name TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    starts_at TEXT NOT NULL,
    ends_at TEXT NOT NULL,
    logs_deadline TEXT NOT NULL,
    organizer TEXT NOT NULL,
    bands TEXT NOT NULL,
    modes TEXT NOT NULL,
    regulation_url TEXT NOT NULL,
    source_url TEXT NOT NULL,
    lifecycle_status TEXT NOT NULL,
    fetch_note TEXT NOT NULL
);


SELECT src.contest_name, NULL, 0, '2026-10-08 00:00:00'
FROM logsp_2026_import AS src
WHERE NOT EXISTS (SELECT 1 FROM contest AS c WHERE c.name = src.contest_name);

SELECT c.id, 2026, src.display_name,
    'Termin zawodów: ' || src.starts_at || ' – ' || src.ends_at || '. Organizator: ' || src.organizer || '. Pasma: ' || src.bands || '. Emisje: ' || src.modes || '. Źródło logSP #' || src.source_id,
       src.lifecycle_status, src.starts_at, src.logs_deadline, '2026-10-08 00:00:00'
FROM logsp_2026_import AS src
JOIN contest AS c ON c.name = src.contest_name
WHERE NOT EXISTS (SELECT 1 FROM contest_edition AS e WHERE e.contest_id = c.id AND e.year = 2026);

SELECT c.id, 'Regulamin 2026 logSP #' || src.source_id,
       'Metadane kalendarza logSP (skrót, nie pełny regulamin). Termin zawodów: ' || src.starts_at || ' – ' || src.ends_at || '. Termin logów: ' || src.logs_deadline || '. Organizator: ' || src.organizer || '. Pasma: ' || src.bands || '. Emisje: ' || src.modes || '. Źródło: ' || src.source_url || CASE WHEN src.regulation_url <> '' THEN '. PDF regulaminu: ' || src.regulation_url ELSE '. W chwili pobrania brak podpiętego PDF regulaminu w logSP.' END,
       '2026-10-08 00:00:00'
FROM logsp_2026_import AS src
JOIN contest AS c ON c.name = src.contest_name
WHERE NOT EXISTS (SELECT 1 FROM contest_rule_note AS n WHERE n.contest_id = c.id AND n.title = 'Regulamin 2026 logSP #' || src.source_id);

DROP TABLE temp.logsp_2026_import;
COMMIT;
